From 167dae984fee88122bdb8c9061d017cd975b4aad Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:09:37 +0100
Subject: [PATCH] libtaskmanager: add a sort mode that sorts tasks by screen

With several screens there was no way to keep the tasks of each screen
together in a task manager. The new SortScreen mode orders tasks by the
position of their screen, then alphabetically within the same screen.

BUG: 480637
---
 libtaskmanager/tasksmodel.cpp | 52 +++++++++++++++++++++++++++++++++++
 libtaskmanager/tasksmodel.h   |  1 +
 2 files changed, 53 insertions(+)

diff --git a/libtaskmanager/tasksmodel.cpp b/libtaskmanager/tasksmodel.cpp
index fd6246a363..f7f7cd5775 100644
--- a/libtaskmanager/tasksmodel.cpp
+++ b/libtaskmanager/tasksmodel.cpp
@@ -85,6 +85,7 @@ public:
     void forceResort();
     bool lessThan(const QModelIndex &left, const QModelIndex &right, bool sortOnlyLaunchers = false) const;
     std::optional<bool> lessThanByVirtualDesktop(const QModelIndex &left, const QModelIndex &right) const;
+    std::optional<bool> lessThanByScreen(const QModelIndex &left, const QModelIndex &right) const;

 private:
     TasksModel *const q;
@@ -728,6 +729,45 @@ std::optional<bool> TasksModel::Private::lessThanByVirtualDesktop(const QModelIn
     return std::nullopt;
 }

+std::optional<bool> TasksModel::Private::lessThanByScreen(const QModelIndex &left, const QModelIndex &right) const
+{
+    const auto screenLessThan = [](const QRect &a, const QRect &b) {
+        if (a.isValid() != b.isValid()) {
+            return a.isValid();
+        }
+        if (QGuiApplication::isRightToLeft() ? a.right() != b.right() : a.x() != b.x()) {
+            return QGuiApplication::isRightToLeft() ? a.right() > b.right() : a.x() < b.x();
+        }
+        return a.y() < b.y();
+    };
+
+    // Groups don't have a screen of their own; use the first screen any of their tasks is on.
+    const auto getScreen = [&screenLessThan](const QModelIndex &model) {
+        const int childCount = model.model()->rowCount(model);
+        if (childCount == 0) {
+            return model.data(AbstractTasksModel::ScreenGeometry).toRect();
+        }
+
+        QRect screen;
+        for (int i = 0; i < childCount; ++i) {
+            const QRect childScreen = model.model()->index(i, 0, model).data(AbstractTasksModel::ScreenGeometry).toRect();
+            if (i == 0 || screenLessThan(childScreen, screen)) {
+                screen = childScreen;
+            }
+        }
+        return screen;
+    };
+
+    const QRect leftScreen = getScreen(left);
+    const QRect rightScreen = getScreen(right);
+
+    if (leftScreen != rightScreen) {
+        return screenLessThan(leftScreen, rightScreen);
+    }
+
+    return std::nullopt;
+}
+
 bool TasksModel::Private::lessThan(const QModelIndex &left, const QModelIndex &right, bool sortOnlyLaunchers) const
 {
     // Launcher tasks go first.
@@ -782,6 +822,12 @@ bool TasksModel::Private::lessThan(const QModelIndex &left, const QModelIndex &r
         return (sortedPreFilterRows.indexOf(left.row()) < sortedPreFilterRows.indexOf(right.row()));
     }

+    if (sortMode == SortScreen) {
+        if (auto result = lessThanByScreen(left, right)) {
+            return *result;
+        }
+    }
+
     // Sort other cases by sort mode.
     switch (sortMode) {
     case SortDisabled: {
@@ -1202,6 +1248,12 @@ void TasksModel::setSortMode(SortMode mode)
             d->sortedPreFilterRows.clear();
         }

+        if (mode == SortScreen) {
+            setSortRole(AbstractTasksModel::ScreenGeometry);
+        } else if (d->sortMode == SortScreen) {
+            setSortRole(Qt::DisplayRole);
+        }
+
         if (mode == SortVirtualDesktop || mode == SortWindowPositionHorizontal) {
             d->virtualDesktopInfo = virtualDesktopInfo();
             setSortRole(AbstractTasksModel::VirtualDesktops);
diff --git a/libtaskmanager/tasksmodel.h b/libtaskmanager/tasksmodel.h
index 9cdad29325..f1cc8683bf 100644
--- a/libtaskmanager/tasksmodel.h
+++ b/libtaskmanager/tasksmodel.h
@@ -98,6 +98,7 @@ public:
         SortActivity, /**< Tasks are sorted by the number of tasks on the activities they're on. */
         SortLastActivated, /**< Tasks are sorted by the last time they were active. */
         SortWindowPositionHorizontal, /**< Tasks are sorted by the virtual desktop they are on, then by window coordinates. */
+        SortScreen, /**< Tasks are sorted by the screen they are on, then alphabetically. */
     };
     Q_ENUM(SortMode)

